def gen(rng):
    tests = ['1 1', '1 5', '2 6', '3 14', '1 100', '2 1', '5 1', '2 2', '3 3', '4 15', '4 16', '100 1', '100 100000', '2 100000',
             '1 100000', '3 100000', '17 100000', '5 99999', '50 2000', '10 10000', '2 99999']
    for _ in range(30):
        tests.append(f'{rng.randint(1, 5)} {rng.randint(1, 40)}')
    for _ in range(4):
        tests.append(f'{rng.randint(1, 100)} {rng.randint(1000, 100000)}')
    # inputs with a large n are padded with trailing spaces so the O(k n^2) brute force is skipped for them
    tests = [t + ' ' * 400 if int(t.split()[1]) > 60 else t for t in tests]
    return tests

